function sql(value) {
  if (value === undefined || value === null || String(value).trim() === '') return 'NULL';
  return "'" + String(value).replace(/'/g, "''") + "'";
}
const body = $json.body || $json;
const jobId = String(body.jobId || body.job_id || '').trim();
const outputUrl = String(body.outputUrl || body.output_url || '').trim();
const uuidRegex = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{12}$/i;
if (!uuidRegex.test(jobId) || !outputUrl) {
  return [{ json: { query: "SELECT false AS ok, 'jobId and outputUrl are required' AS error;" } }];
}
const query = `
SELECT
  true AS ok,
  gj.job_id AS "jobId",
  gj.avatar,
  gj.scene,
  gj.asset_type AS "assetType",
  gj.platform,
  gj.prompt_pack AS "promptPack",
  gj.request_payload AS "requestPayload",
  ac.avatar_short AS "avatarShort",
  ${sql(outputUrl)} AS "outputUrl"
FROM generation_jobs gj
LEFT JOIN avatar_catalog ac ON ac.avatar = gj.avatar
WHERE gj.job_id = ${sql(jobId)}::uuid
LIMIT 1;
`;
return [{ json: { query } }];

const fs = require('fs');
const path = require('path');
function slug(value, fallback = '') {
  return String(value || fallback || '').trim().toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '').replace(/-{2,}/g, '-');
}
const row = $input.first()?.json || {};
if (!row.ok || !row.jobId || !row.outputUrl) return [{ json: { ok: false, error: row.error || 'Generation job context not found' } }];
const gateway = await this.helpers.httpRequest({
  method: 'POST',
  url: 'http://ai-gateway:8095/comfy/download-output',
  headers: { 'Content-Type': 'application/json', 'X-Request-Id': 'canon-ingest-' + row.jobId },
  body: { outputUrl: row.outputUrl },
  json: true,
  timeout: 120000,
});
if (!gateway?.ok || !gateway.base64) return [{ json: { ok: false, error: gateway?.error || 'Comfy output download failed', gateway } }];
const avatar = slug(row.avatar);
const safeJob = String(row.jobId).replace(/[^a-zA-Z0-9_-]/g, '-');
const inputDir = '/home/node/.n8n-files/inbox/canon-' + safeJob + '-' + Date.now();
fs.mkdirSync(inputDir, { recursive: true });
const ext = gateway.mimeType === 'image/jpeg' ? 'jpg' : gateway.mimeType === 'image/webp' ? 'webp' : 'png';
const fileName = avatar + '-canon-portrait-' + safeJob + '.' + ext;
const filePath = path.join(inputDir, fileName);
fs.writeFileSync(filePath, Buffer.from(gateway.base64, 'base64'));
return [{ json: {
  ok: true,
  jobId: row.jobId,
  avatar: row.avatar,
  avatarShort: row.avatarShort || avatar.split('-')[0] || avatar,
  scene: 'portrait-canon',
  assetType: row.assetType || 'raw-image',
  workflow: 'character-canon-portrait',
  model: 'flux1-dev-fp8 + uso-flux1',
  seed: 0,
  version: 1,
  promptPack: row.promptPack || {},
  requestPayload: row.requestPayload || {},
  outputUrl: row.outputUrl,
  inputDir,
  downloadedFileName: fileName,
  downloadedFile: filePath,
  downloadedBase64: gateway.base64,
  mimeType: gateway.mimeType || 'image/png',
  byteLength: gateway.byteLength || 0,
  sha256: gateway.sha256,
  comfyFilename: gateway.filename,
  comfySubfolder: gateway.subfolder,
} }];

const row = $input.first()?.json || {};
if (row.ok === false || row.ok === 'f') return [{ json: { ok: false, message: row.error || row.message || 'Canon portrait output could not be ingested.' } }];
const reference = typeof row.reference === 'string' ? JSON.parse(row.reference) : row.reference;
const generationJob = typeof row.generation_job === 'string' ? JSON.parse(row.generation_job) : row.generation_job;
return [{ json: { ok: true, reference, generationJob } }];
